// The header of every record: field -> [offset, kind]
export const HEADER = Object.freeze({
  size: [0, 'u32'],
  type: [4, 'u32'],
  flags: [8, 'u32'],
  window: [12, 'u32'],
  timestamp: [16, 'u64'],
  device: [24, 'u32'],
  sequence: [28, 'u32'],
});

